import io
def mk(b, **kw): return io.TextIOWrapper(io.BytesIO(b), encoding="utf-8", **kw)
t = mk(b"hello\nworld\r\nthird\rfourth")
print(t.read(3), repr(t.readline()), repr(t.readline()), repr(t.read()), repr(t.read()))
print(list(mk(b"a\nb\r\nc\rd")), list(mk(b"a\nb\r\nc\rd", newline="")), list(mk(b"a\nb\r\nc\rd", newline="\n")), list(mk(b"a\nb\r\nc\rd", newline="\r\n")))
print(mk("héllo wörld\n日本語".encode()).read(), mk("日本語".encode()).read(1), mk("日本語\nx".encode()).readlines())
print(mk(b"abc\ndef").readline(2), mk(b"abc\ndef").readlines(2))
b = io.BytesIO(); w = io.TextIOWrapper(b, "utf-8"); print(w.write("hi\n"), w.write("é")); w.flush(); print(b.getvalue())
b = io.BytesIO(); w = io.TextIOWrapper(b, "utf-8", newline="\r\n"); w.write("a\nb"); w.flush(); print(b.getvalue())
b = io.BytesIO(); w = io.TextIOWrapper(b, "latin-1"); w.write("é"); w.flush(); print(b.getvalue())
t = mk(b"x\ny")
print(t.encoding, t.errors, t.readable(), t.writable(), t.seekable(), t.closed, t.line_buffering, isinstance(t, io.TextIOBase))
t.close(); print(t.closed)
try: t.read()
except ValueError as e: print("ValueError", e)
with mk(b"q\nr") as f:
    print([l for l in f])
t = mk(b"abc"); bb = t.detach(); print(type(bb).__name__)
try: io.TextIOWrapper(io.BytesIO(), newline="x")
except ValueError as e: print("ValueError", e)
try: mk(b"\xff").read()
except UnicodeDecodeError as e: print("UnicodeDecodeError")
print(mk(b"\xff", errors="replace").read() if False else "skip")
print(io.text_encoding(None), io.text_encoding("utf-8"))
t = mk(b"ab\ncd"); t.seek(3); print(t.read(), t.tell())
